with base as (select l.operation_id, l.opened_at_ms, o.attempt_count, o.completed_at_ms, o.final_code_id, c.pool_id, (l.opened_at_ms>=1778320800000 and l.opened_at_ms<1778324400000) as is_inc from logical_operations l join outcome_events o using(operation_id) join execution_cells c using(cell_id) where l.opened_at_ms>=1778320800000 and l.opened_at_ms<1778328000000)
